// Some portions generated by Codex
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const vm = require('node:vm');
const { spawnSync } = require('node:child_process');
const { classicCompilerOptions, workbenchRoot } = require('./workbench-scripts.js');

let sharing;
test.before(() => {
    const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-query-sharing-'));
    const output = path.join(directory, 'querySharing.js');
    const compilation = spawnSync(process.execPath, [
        path.join(workbenchRoot, 'node_modules/typescript/bin/tsc'),
        ...classicCompilerOptions(), '--target', 'ES2017', '--lib', 'ES2017,DOM', '--skipLibCheck',
        '--outFile', output, path.join(workbenchRoot, 'src/main/frontend/classic/querySharing.ts')
    ], { encoding: 'utf8', timeout: 30000 });
    assert.equal(compilation.status, 0,
        `The query-sharing helpers must compile independently:\n${compilation.stdout}${compilation.stderr}`);
    const context = vm.createContext({ workbench: {}, URL, URLSearchParams });
    vm.runInContext(fs.readFileSync(output, 'utf8'), context, { filename: output });
    sharing = context.workbench.querySharing;
    assert.equal(typeof sharing.buildCurlCommand, 'function');
    assert.equal(typeof sharing.buildShareLink, 'function');
});

const defaults = {
    serverUrl: 'https://rdf.example:9443/custom/server/',
    repositoryId: 'demo',
    workbenchUrl: 'https://workbench.example:8443/apps/rdf4j-workbench/repositories/demo/query',
    query: 'SELECT * WHERE { ?s ?p ?o } LIMIT 10',
    queryType: 'SELECT',
    infer: false,
};

/**
 * Let a real POSIX shell parse the generated command, with curl replaced by an inert argument printer.
 * No curl executable, network request or SPARQL evaluation is involved. Test inputs are fixed benign fixtures.
 */
function capturedArguments(command) {
    const parsed = spawnSync('sh', ['-c', 'curl() { printf "%s\\0" "$@"; }\n' + command], {
        encoding: 'utf8', timeout: 10000,
        env: Object.assign({}, process.env, { QUERY_SHARING_SENTINEL: 'must-not-expand' })
    });
    assert.equal(parsed.status, 0, `The command must be valid shell syntax: ${parsed.stderr}`);
    assert.equal(parsed.stderr, '', 'the generated command must contain only the inert curl invocation');
    assert.ok(parsed.stdout.endsWith('\0'), 'curl must receive its arguments without shell redirection');
    return parsed.stdout.slice(0, -1).split('\0');
}

function request(options = {}) {
    const command = sharing.buildCurlCommand(Object.assign({}, defaults, options));
    const args = capturedArguments(command);
    const urls = args.filter(value => /^https?:\/\//.test(value));
    assert.equal(urls.length, 1, 'exactly one HTTP endpoint must be exported');
    const parameters = new URLSearchParams();
    const headers = [];
    let method;
    for (let index = 0; index < args.length; index++) {
        if (args[index] === '--data-urlencode') {
            const field = args[++index];
            const equals = field.indexOf('=');
            assert.ok(equals > 0, 'a literal form value must use curl\'s name=content syntax');
            parameters.append(field.slice(0, equals), field.slice(equals + 1));
        } else if (args[index] === '--data-raw' || args[index] === '--data' || args[index] === '-d') {
            new URLSearchParams(args[++index]).forEach((value, name) => parameters.append(name, value));
        } else if (args[index] === '--header' || args[index] === '-H') {
            headers.push(args[++index]);
        } else if (args[index] === '--request' || args[index] === '-X') {
            method = args[++index];
        }
    }
    assert.equal(method || (parameters.size ? 'POST' : 'GET'), 'POST');
    return { command, args, endpoint: new URL(urls[0]), parameters, headers };
}

test('cURL preserves the configured remote server origin and context path', () => {
    const result = request();
    assert.equal(result.endpoint.href, 'https://rdf.example:9443/custom/server/repositories/demo');
    assert.equal(result.endpoint.search, '');
    assert.equal(result.endpoint.hash, '');
    assert.equal(result.parameters.get('query'), defaults.query);
});

test('cURL quotes the endpoint path as well as the query text', () => {
    const result = request({ serverUrl: "https://rdf.example:9443/it's/a/server" });
    assert.equal(result.endpoint.href, "https://rdf.example:9443/it's/a/server/repositories/demo");
});

for (const serverHost of ['localhost', 'LOCALHOST', 'localhost.', '127.0.0.1', '127.2.3.4', '[::1]']) {
    test(`cURL maps ${serverHost} to the whole Workbench origin while retaining the server path`, () => {
        const result = request({ serverUrl: `http://${serverHost}:8080/custom/rdf4j-server/` });
        assert.equal(result.endpoint.href,
            'https://workbench.example:8443/custom/rdf4j-server/repositories/demo');
    });
}

test('cURL does not retain an internal port when Workbench uses the default HTTPS port', () => {
    const result = request({ serverUrl: 'http://localhost:8080/rdf4j-server',
        workbenchUrl: 'https://public.example/rdf4j-workbench/repositories/demo/query' });
    assert.equal(result.endpoint.href, 'https://public.example/rdf4j-server/repositories/demo');
    assert.equal(result.endpoint.port, '');
});

test('cURL retains the configured server port when Workbench and server both use loopback', () => {
    for (const [serverHost, workbenchHost] of [['localhost', 'localhost'], ['[::1]', '127.0.0.1']]) {
        const serverUrl = `http://${serverHost}:8181/rdf4j-server`;
        const result = request({ serverUrl,
            workbenchUrl: `http://${workbenchHost}:8080/rdf4j-workbench/repositories/demo/query` });
        assert.equal(result.endpoint.href, serverUrl + '/repositories/demo');
    }
});

test('cURL does not rewrite non-loopback hosts containing localhost or an IP prefix', () => {
    for (const host of ['localhost.example.org', '127.0.0.1.example.org', '192.168.1.2']) {
        assert.equal(request({ serverUrl: `http://${host}:9090/server` }).endpoint.href,
            `http://${host}:9090/server/repositories/demo`);
    }
});

test('cURL encodes the repository ID as one path segment', () => {
    for (const repositoryId of ['SYSTEM@localhost', 'repository / å?#%']) {
        const result = request({ repositoryId });
        assert.equal(result.endpoint.href,
            'https://rdf.example:9443/custom/server/repositories/' + encodeURIComponent(repositoryId));
        assert.equal(result.endpoint.search, '');
        assert.equal(result.endpoint.hash, '');
    }
});

test('cURL preserves inference and maps the query timeout to RDF4J protocol fields', () => {
    for (const infer of [false, true]) {
        for (const timeout of [60, '120', 2147483647]) {
            const result = request({ infer, timeout, queryLanguage: 'SPARQL' });
            assert.equal(result.parameters.get('infer'), String(infer));
            assert.equal(result.parameters.get('queryLn'), 'SPARQL');
            assert.equal(result.parameters.get('timeout'), String(timeout));
            assert.equal(result.parameters.has('query-timeout'), false);
        }
    }
    const unlimited = request({ timeout: 0 }).parameters.get('timeout');
    assert.ok(unlimited === null || unlimited === '0', 'zero must preserve unlimited server execution');
});

test('cURL rejects timeouts that the RDF4J protocol cannot represent', () => {
    for (const timeout of [-1, 1.5, 'not-a-timeout', NaN, Infinity, 2147483648, '2147483648']) {
        assert.throws(() => sharing.buildCurlCommand(Object.assign({}, defaults, { timeout })),
            /timeout|seconds/i, `invalid timeout: ${String(timeout)}`);
    }
});

test('cURL carries an explicitly selected LMDB execution strategy', () => {
    assert.equal(request({ forcedStrategy: 'irKernel' }).parameters.get('lmdb-forced-strategy'), 'irKernel');
    assert.equal(request({ forcedStrategy: '' }).parameters.has('lmdb-forced-strategy'), false);
});

test('cURL negotiates tuple and boolean JSON results and graph Turtle results', () => {
    for (const queryType of ['SELECT', 'ASK']) {
        assert.ok(request({ queryType }).headers.includes('Accept: application/sparql-results+json'), queryType);
    }
    for (const queryType of ['CONSTRUCT', 'DESCRIBE']) {
        assert.ok(request({ queryType }).headers.includes('Accept: text/turtle'), queryType);
    }
});

test('cURL permits graph and tuple results when the editor cannot identify the query type', () => {
    const query = 'VERSION "1.2"\nCONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o }';
    // The bundled YASQE parser predates VERSION declarations and reports no type for this valid query.
    for (const queryType of [undefined, null, '', 'UNKNOWN']) {
        const result = request({ query, queryType });
        const accept = result.headers.find(header => /^Accept:/i.test(header)) || '';
        assert.match(accept, /application\/sparql-results\+json/, String(queryType));
        assert.match(accept, /text\/turtle/, String(queryType));
        assert.equal(result.parameters.get('query'), query);
    }
});

test('cURL shell quoting preserves query metacharacters, Unicode and newlines literally', () => {
    const query = 'PREFIX ex: <https://example.org/ns#>\n'
        + 'SELECT ?s WHERE {\n  ?s ex:label "Håvard café 😀 + 100% & = @" .\n'
        + '  # apostrophe \' double quote " backslash \\ dollar $QUERY_SHARING_SENTINEL\n'
        + '  # command-looking text $(printf substitution) `printf backticks` ; & | < >\n}';
    const result = request({ query });
    assert.equal(result.parameters.get('query'), query, 'the shell and form encoding must preserve every character');
    assert.equal(result.parameters.getAll('query').length, 1);
    assert.equal(request({ query: '@query-file.sparql' }).parameters.get('query'), '@query-file.sparql',
        'query content must not become curl\'s filename syntax');
});

test('cURL exports protocol fields without Workbench form actions or credentials', () => {
    const result = request({ action: 'exec', ref: 'saved-query', limit: 20, queryTimeout: 500,
        username: 'private-user', password: 'private-secret', cookie: 'session=private-session' });
    assert.deepEqual(Array.from(result.parameters.keys()).sort(), ['infer', 'query', 'queryLn']);
    assert.equal(result.endpoint.username, '');
    assert.equal(result.endpoint.password, '');
    assert.equal(result.args.some(value => /^Authorization:|^Cookie:/i.test(value)), false);
    assert.doesNotMatch(result.command, /private-user|private-secret|private-session/);
});

test('cURL excludes server URL credentials, query parameters and fragments', () => {
    const result = request({ serverUrl:
        'https://private-user:private-secret@rdf.example:9443/server?token=private-token#private-fragment' });
    assert.equal(result.endpoint.href, 'https://rdf.example:9443/server/repositories/demo');
    assert.doesNotMatch(result.command, /private-user|private-secret|private-token|private-fragment/);
});

test('cURL refuses missing or non-HTTP server endpoints with an informative error', () => {
    for (const serverUrl of ['', ' ', 'file:///var/lib/rdf4j', 'ftp://server.example/repository',
        'javascript:alert(1)', 'not a server URL']) {
        assert.throws(() => sharing.buildCurlCommand(Object.assign({}, defaults, { serverUrl })),
            /server|endpoint|HTTP/i, serverUrl);
    }
});

test('a share link replaces stale URL state with one lossless query fragment', () => {
    const query = 'PREFIX ex: <https://example.org/ns#>\nSELECT * { ?s ex:p "å + % & = #" }';
    const link = new URL(sharing.buildShareLink(defaults.workbenchUrl
        + '?query=old&ref=id&action=exec&infer=true#query=older&ignored=yes', query));
    assert.equal(link.origin + link.pathname, defaults.workbenchUrl);
    assert.equal(link.search, '');
    assert.deepEqual(Array.from(new URLSearchParams(link.hash.slice(1))), [['query', query]]);
});

test('an explicitly empty shared query survives as an empty query fragment', () => {
    const link = new URL(sharing.buildShareLink(defaults.workbenchUrl + '?ref=id#query=old', ''));
    assert.equal(link.search, '');
    assert.deepEqual(Array.from(new URLSearchParams(link.hash.slice(1))), [['query', '']]);
});
